<script>
(function(){
 const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
 let activeLookup=null;
 function openModal(id,input){const m=document.getElementById(id);if(!m)return;m.classList.add('open');if(input){input.value='';input.dataset.dirty='1';setTimeout(()=>input.focus(),30)}const list=id==='personModal'?document.getElementById('personResults'):document.getElementById('itemResults');if(list)list.innerHTML='';}
 function closeModal(id){const m=document.getElementById(id);if(m)m.classList.remove('open')}
 document.querySelectorAll('[data-close-modal]').forEach(b=>b.addEventListener('click',()=>closeModal(b.dataset.closeModal)));
 const negotiationBtn=document.getElementById('orcOpenNegotiation');if(negotiationBtn)negotiationBtn.addEventListener('click',()=>{const m=document.getElementById('orcNegotiationModal');if(m)m.classList.add('open');});
 // V11.36.4.1: modal de pesquisa só fecha pelo botão Fechar ou após selecionar o registro.
 // Cliques no fundo, seleção de texto e limpeza do campo não encerram a pesquisa.
 const roleNames={customer:'cliente',seller:'vendedor',professional:'profissional',carrier:'transportadora'};
 const personCreateBtn=document.getElementById('personCreateBtn');const customerCreateUrl=<?= json_encode($customerCreateUrl,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>;
 if(personCreateBtn)personCreateBtn.addEventListener('click',()=>{window.open(customerCreateUrl,'orcamento_cadastro_cliente');});
 document.querySelectorAll('.lookup-btn').forEach(b=>b.addEventListener('click',()=>{activeLookup={role:b.dataset.role,targetId:b.dataset.targetId,targetName:b.dataset.targetName};document.getElementById('personModalTitle').textContent='Buscar '+(roleNames[activeLookup.role]||'pessoa');if(personCreateBtn)personCreateBtn.style.display=activeLookup.role==='customer'?'inline-flex':'none';openModal('personModal',document.getElementById('personSearch'));}));
 const clearCustomer=document.getElementById('btnClearCustomer');if(clearCustomer)clearCustomer.addEventListener('click',()=>{const id=document.getElementById('person_id'),nm=document.getElementById('person_name');if(id)id.value='0';if(nm)nm.value='';clearCustomer.style.display='none';const cn=document.getElementById('customer_name');if(cn)cn.focus();});
 const itemBtn=document.getElementById('btnBuscarItem');if(itemBtn)itemBtn.addEventListener('click',()=>openModal('itemModal',document.getElementById('itemSearch')));
 document.querySelectorAll('[data-lookup-input]').forEach(i=>i.addEventListener('focus',()=>{i.dataset.lookupFocused='1';document.querySelectorAll('[data-lookup-input]').forEach(j=>{if(j!==i)delete j.dataset.lookupFocused;});}));
 document.addEventListener('keydown',e=>{if(e.key!=='F8')return;e.preventDefault();const focused=document.querySelector('[data-lookup-input][data-lookup-focused="1"]');if(focused){const role=focused.dataset.lookupInput;if(role==='item'&&itemBtn){itemBtn.click();return}const b=document.querySelector('.lookup-btn[data-role="'+role+'"]');if(b){b.click();return}}if(itemBtn&&<?=($step===2?'true':'false')?>){itemBtn.click();return}const first=document.querySelector('.lookup-btn');if(first)first.click();});
 function fetchJson(url){return fetch(url,{credentials:'same-origin'}).then(r=>r.text().then(t=>{let j;try{j=JSON.parse(t)}catch(x){throw new Error('Resposta inválida da pesquisa.')}if(!r.ok||!j.ok)throw new Error(j.message||'Falha na pesquisa.');return j;}));}
 const orcMethods=<?= $orcMethodsJson ?: '[]' ?>||[];const orcStoredPayments=<?= $orcPaymentsJson ?: '[]' ?>||[];const orcMethodMap=Object.fromEntries(orcMethods.map(m=>[String(m.id),m]));const orcHasFutureDelivery=<?= $hasFutureDelivery?'true':'false' ?>;let orcQuoteTotal=<?= json_encode((float)($order['total_general']??0)) ?>;const orcQuoteSubtotal=<?= json_encode((float)($order['total_products']??0)+(float)($order['total_services']??0)) ?>;const orcMaxDiscountPercent=<?= $maxDiscountPercent===null?'null':json_encode((float)$maxDiscountPercent) ?>;const orcItemGrossForLimit=<?= json_encode((float)$itemGrossForDiscountLimit) ?>;const orcItemDiscountForLimit=<?= json_encode((float)$itemDiscountForLimit) ?>;
 function parsePay(v){v=String(v??'').trim();if(v.includes(','))v=v.replace(/\./g,'').replace(',','.');return Number(v.replace(/[^0-9.-]/g,''))||0}function fmtPay(v){return Number(v||0).toFixed(2).replace('.',',')}
 function orcAdjustmentKey(el){return el.id==='orcDiscountPct'?'discount_percent':el.id==='orcDiscountAmount'?'discount_amount':el.id==='orcAdditionPct'?'addition_percent':el.id==='orcAdditionAmount'?'addition_amount':'freight'}
 function orcRebalancePayments(previousTotal,newTotal){const rows=Array.from(document.querySelectorAll('.orc-pay-row'));if(!rows.length)return;const previousSum=orcPaySum();if(Math.abs(previousSum-previousTotal)>.011)return;let delta=Math.round((newTotal-previousTotal)*100)/100;if(Math.abs(delta)<=.009)return;if(delta>0){const row=rows[rows.length-1],amt=row?.querySelector('.orc-pay-amount');if(amt){amt.value=fmtPay(parsePay(amt.value)+delta);orcPayInstallments(row,true)}return}let remaining=-delta;for(let i=rows.length-1;i>=0&&remaining>.009;i--){const amt=rows[i].querySelector('.orc-pay-amount');if(!amt)continue;const current=parsePay(amt.value),take=Math.min(current,remaining);amt.value=fmtPay(Math.max(0,current-take));remaining=Math.round((remaining-take)*100)/100;orcPayInstallments(rows[i],true)} }
