<script>
(function(){
  function lockFaturadoQuote(){
    document.documentElement.classList.add('orc-faturado-readonly');
    document.querySelectorAll('form').forEach(function(form){
      form.addEventListener('submit',function(ev){ev.preventDefault();ev.stopPropagation();},true);
      form.querySelectorAll('input,select,textarea,button').forEach(function(el){
        if((el.getAttribute('type')||'').toLowerCase()!=='hidden') el.disabled=true;
      });
    });
    document.querySelectorAll('a[href*="edit_item="]').forEach(function(a){a.style.display='none';});
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',lockFaturadoQuote);
  else lockFaturadoQuote();
})();
</script>
